*** Begin Patch
*** Add File: /workspace/submission/infra/main.tf
+terraform {
+  required_providers {
+    aws = { source = "hashicorp/aws", version = "6.51.0" }
+  }
+  backend "local" { path = "terraform.tfstate" }
+}
+variable "config" { type = map(string) }
+provider "aws" {
+  region                      = var.config.region
+  access_key                  = "test"
+  secret_key                  = "test"
+  skip_credentials_validation = true
+  skip_metadata_api_check     = true
+  skip_requesting_account_id  = true
+  s3_use_path_style           = true
+  endpoints {
+    ec2 = var.config.aws_endpoint_url
+    elbv2 = var.config.aws_endpoint_url
+    ecs = var.config.aws_endpoint_url
+    rds = var.config.aws_endpoint_url
+    sqs = var.config.aws_endpoint_url
+    lambda = var.config.aws_endpoint_url
+    dynamodb = var.config.aws_endpoint_url
+    elasticache = var.config.aws_endpoint_url
+    s3 = var.config.aws_endpoint_url
+    scheduler = var.config.aws_endpoint_url
+    cognitoidp = var.config.aws_endpoint_url
+    iam = var.config.aws_endpoint_url
+    kms = var.config.aws_endpoint_url
+    cloudwatchlogs = var.config.aws_endpoint_url
+    sts = var.config.aws_endpoint_url
+  }
+  default_tags { tags = { ClearLedgerDeployment = var.config.resource_prefix } }
+}
+locals {
+  p = var.config.resource_prefix
+  roles = toset(["ecs_execution", "ecs_task", "projector", "relay", "archiver", "scheduler"])
+  logs = { api = "api", projector = "projector", relay = "outbox-relay", archiver = "audit-archiver" }
+  common_env = {
+    AWS_REGION = var.config.region, AWS_DEFAULT_REGION = var.config.region,
+    AWS_ACCESS_KEY_ID = "test", AWS_SECRET_ACCESS_KEY = "test", AWS_ENDPOINT_URL = var.config.aws_endpoint_url
+  }
+  database_url = "postgres://${urlencode(var.config.db_username)}:${urlencode(var.config.db_password)}@${aws_db_instance.db.address}:${aws_db_instance.db.port}/${var.config.db_name}"
+  valkey_url = "redis://${aws_elasticache_replication_group.cache.primary_endpoint_address}:6379"
+  issuer = "${var.config.aws_endpoint_url}/${aws_cognito_user_pool.pool.id}"
+}
+resource "aws_vpc" "main" {
+  cidr_block = "10.42.0.0/16"
+  enable_dns_support = true
+  enable_dns_hostnames = true
+  tags = { Name = "${local.p}-vpc" }
+}
+resource "aws_subnet" "public" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index}.0/24"
+  availability_zone = "${var.config.region}${count.index == 0 ? "a" : "b"}"
+  map_public_ip_on_launch = true
+  tags = { Name = "${local.p}-public-${count.index}" }
+}
+resource "aws_subnet" "private" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index + 10}.0/24"
+  availability_zone = "${var.config.region}${count.index == 0 ? "a" : "b"}"
+  map_public_ip_on_launch = false
+  tags = { Name = "${local.p}-private-${count.index}" }
+}
+resource "aws_internet_gateway" "main" {
+  vpc_id = aws_vpc.main.id
+  tags = { Name = "${local.p}-igw" }
+}
+resource "aws_route_table" "public" {
+  vpc_id = aws_vpc.main.id
+  route { cidr_block = "0.0.0.0/0", gateway_id = aws_internet_gateway.main.id }
+  tags = { Name = "${local.p}-public" }
+}
+resource "aws_route_table" "private" {
+  vpc_id = aws_vpc.main.id
+  tags = { Name = "${local.p}-private" }
+}
+resource "aws_route_table_association" "public" {
+  count = 2
+  subnet_id = aws_subnet.public[count.index].id
+  route_table_id = aws_route_table.public.id
+}
+resource "aws_route_table_association" "private" {
+  count = 2
+  subnet_id = aws_subnet.private[count.index].id
+  route_table_id = aws_route_table.private.id
+}
+resource "aws_security_group" "alb" {
+  name = "${local.p}-alb"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 80, to_port = 80, protocol = "tcp", cidr_blocks = ["0.0.0.0/0"] }
+  egress { from_port = 8080, to_port = 8080, protocol = "tcp", cidr_blocks = [aws_vpc.main.cidr_block] }
+}
+resource "aws_security_group" "ecs" {
+  name = "${local.p}-ecs"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 8080, to_port = 8080, protocol = "tcp", security_groups = [aws_security_group.alb.id] }
+  egress { from_port = 0, to_port = 0, protocol = "-1", cidr_blocks = ["0.0.0.0/0"] }
+}
+resource "aws_security_group" "rds" {
+  name = "${local.p}-rds"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 5432, to_port = 5432, protocol = "tcp", cidr_blocks = [aws_vpc.main.cidr_block] }
+  egress = []
+}
+resource "aws_security_group" "valkey" {
+  name = "${local.p}-valkey"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 6379, to_port = 6379, protocol = "tcp", cidr_blocks = [aws_vpc.main.cidr_block] }
+  egress = []
+}
+resource "aws_kms_key" "keys" {
+  for_each = toset(["database", "messaging", "projection", "audit"])
+  description = "${local.p}-${each.key}"
+  enable_key_rotation = true
+  deletion_window_in_days = 10
+  tags = { Name = "${local.p}-${each.key}", ClearLedgerKeyUsage = each.key }
+}
+resource "aws_kms_alias" "keys" {
+  for_each = aws_kms_key.keys
+  name = "alias/${local.p}-${each.key}"
+  target_key_id = each.value.key_id
+}
+resource "aws_cloudwatch_log_group" "logs" {
+  for_each = local.logs
+  name = "/clearledger/${local.p}/${each.value}"
+  retention_in_days = 14
+}
+resource "aws_db_subnet_group" "db" {
+  name = "${local.p}-db"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_db_instance" "db" {
+  identifier = "${local.p}-postgres"
+  engine = "postgres"
+  engine_version = "16.3"
+  instance_class = "db.t4g.micro"
+  allocated_storage = 20
+  db_name = var.config.db_name
+  username = var.config.db_username
+  password = var.config.db_password
+  storage_encrypted = true
+  kms_key_id = aws_kms_key.keys["database"].arn
+  publicly_accessible = false
+  skip_final_snapshot = true
+  db_subnet_group_name = aws_db_subnet_group.db.name
+  vpc_security_group_ids = [aws_security_group.rds.id]
+  apply_immediately = true
+  lifecycle { prevent_destroy = true }
+}
+resource "aws_sqs_queue" "dlq" {
+  name = "${local.p}-dlq"
+  kms_master_key_id = aws_kms_key.keys["messaging"].arn
+  message_retention_seconds = 1209600
+}
+resource "aws_sqs_queue" "main" {
+  name = "${local.p}-events"
+  kms_master_key_id = aws_kms_key.keys["messaging"].arn
+  visibility_timeout_seconds = 3
+  receive_wait_time_seconds = 2
+  message_retention_seconds = 172800
+  redrive_policy = jsonencode({ deadLetterTargetArn = aws_sqs_queue.dlq.arn, maxReceiveCount = 4 })
+}
+resource "aws_dynamodb_table" "projection" {
+  name = "${local.p}-projections"
+  billing_mode = "PAY_PER_REQUEST"
+  hash_key = "PK"
+  range_key = "SK"
+  dynamic "attribute" {
+    for_each = toset(["PK", "SK", "GSI1PK", "GSI1SK"])
+    content { name = attribute.value, type = "S" }
+  }
+  global_secondary_index { name = "AccountIndex", hash_key = "GSI1PK", range_key = "GSI1SK", projection_type = "ALL" }
+  point_in_time_recovery { enabled = true }
+  server_side_encryption { enabled = true, kms_key_arn = aws_kms_key.keys["projection"].arn }
+  lifecycle { prevent_destroy = true }
+}
+resource "aws_elasticache_subnet_group" "cache" {
+  name = "${local.p}-cache"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_elasticache_replication_group" "cache" {
+  replication_group_id = "${local.p}-valkey"
+  description = "${local.p} projection cache"
+  engine = "valkey"
+  engine_version = "8.0"
+  node_type = "cache.t4g.micro"
+  num_cache_clusters = 1
+  port = 6379
+  subnet_group_name = aws_elasticache_subnet_group.cache.name
+  security_group_ids = [aws_security_group.valkey.id]
+  apply_immediately = true
+}
+resource "aws_s3_bucket" "audit" {
+  bucket = "${local.p}-audit"
+  force_destroy = true
+  lifecycle { prevent_destroy = true }
+}
+resource "aws_s3_bucket_versioning" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  versioning_configuration { status = "Enabled" }
+}
+resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  rule { apply_server_side_encryption_by_default { sse_algorithm = "aws:kms", kms_master_key_id = aws_kms_key.keys["audit"].arn } }
+}
+resource "aws_s3_bucket_public_access_block" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  block_public_acls = true
+  block_public_policy = true
+  ignore_public_acls = true
+  restrict_public_buckets = true
+}
+resource "aws_cognito_user_pool" "pool" { name = "${local.p}-auth" }
+resource "aws_cognito_resource_server" "scopes" {
+  identifier = "clearledger"
+  name = "${local.p}-scopes"
+  user_pool_id = aws_cognito_user_pool.pool.id
+  dynamic "scope" {
+    for_each = toset(["read", "write", "admin"])
+    content { scope_name = scope.value, scope_description = "ClearLedger ${scope.value}" }
+  }
+}
+resource "aws_cognito_user_pool_client" "clients" {
+  for_each = toset(["read", "write", "admin"])
+  name = "${local.p}-${each.key}"
+  user_pool_id = aws_cognito_user_pool.pool.id
+  generate_secret = true
+  allowed_oauth_flows_user_pool_client = true
+  allowed_oauth_flows = ["client_credentials"]
+  allowed_oauth_scopes = ["clearledger/${each.key}"]
+  depends_on = [aws_cognito_resource_server.scopes]
+}
+resource "aws_iam_role" "roles" {
+  for_each = local.roles
+  name = "${local.p}-${each.key}"
+  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Action = "sts:AssumeRole", Principal = { Service = startswith(each.key, "ecs_") ? "ecs-tasks.amazonaws.com" : each.key == "scheduler" ? "scheduler.amazonaws.com" : "lambda.amazonaws.com" } }] })
+  tags = { ClearLedgerRole = each.key }
+}
+resource "aws_lambda_function" "workers" {
+  for_each = toset(["projector", "relay", "archiver"])
+  function_name = "${local.p}-${each.key}"
+  role = aws_iam_role.roles[each.key].arn
+  package_type = "Image"
+  image_uri = var.config["${each.key}_image"]
+  timeout = 3
+  memory_size = 256
+  environment {
+    variables = merge(local.common_env, { CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.logs[each.key].name }, each.key == "projector" ? {
+      PROJECTION_TABLE = aws_dynamodb_table.projection.name, VALKEY_URL = local.valkey_url
+    } : each.key == "relay" ? {
+      DATABASE_URL = local.database_url, SQS_QUEUE_URL = aws_sqs_queue.main.url, OUTBOX_BATCH_SIZE = "50"
+    } : {
+      DATABASE_URL = local.database_url, AUDIT_BUCKET = aws_s3_bucket.audit.id, AUDIT_PREFIX = "ledger-audit/"
+    })
+  }
+}
+resource "aws_lambda_event_source_mapping" "projector" {
+  event_source_arn = aws_sqs_queue.main.arn
+  function_name = aws_lambda_function.workers["projector"].arn
+  enabled = true
+  batch_size = 5
+  maximum_batching_window_in_seconds = 0
+  function_response_types = ["ReportBatchItemFailures"]
+  depends_on = [aws_iam_role_policy.canonical]
+}
+resource "aws_scheduler_schedule" "workers" {
+  for_each = { relay = "rate(1 minute)", archiver = "rate(5 minutes)" }
+  name = "${local.p}-${each.key}"
+  state = "ENABLED"
+  schedule_expression = each.value
+  flexible_time_window { mode = "OFF" }
+  target { arn = aws_lambda_function.workers[each.key].arn, role_arn = aws_iam_role.roles["scheduler"].arn, input = "{}" }
+  depends_on = [aws_iam_role_policy.canonical]
+}
+resource "aws_lb" "api" {
+  name = "${local.p}-api"
+  internal = false
+  load_balancer_type = "application"
+  subnets = aws_subnet.public[*].id
+  security_groups = [aws_security_group.alb.id]
+}
+resource "aws_lb_target_group" "api" {
+  name = "${local.p}-api"
+  port = 8080
+  protocol = "HTTP"
+  target_type = "ip"
+  vpc_id = aws_vpc.main.id
+  health_check { path = "/health/ready", protocol = "HTTP", matcher = "200" }
+}
+resource "aws_lb_listener" "api" {
+  load_balancer_arn = aws_lb.api.arn
+  port = 80
+  protocol = "HTTP"
+  default_action { type = "forward", target_group_arn = aws_lb_target_group.api.arn }
+}
+resource "aws_ecs_cluster" "api" {
+  name = "${local.p}-cluster"
+  setting { name = "containerInsights", value = "enabled" }
+}
+resource "aws_ecs_task_definition" "api" {
+  family = "${local.p}-api"
+  requires_compatibilities = ["FARGATE"]
+  network_mode = "awsvpc"
+  cpu = "256"
+  memory = "512"
+  execution_role_arn = aws_iam_role.roles["ecs_execution"].arn
+  task_role_arn = aws_iam_role.roles["ecs_task"].arn
+  container_definitions = jsonencode([{ name = "api", image = var.config.api_image, essential = true,
+    portMappings = [{ containerPort = 8080, hostPort = 8080, protocol = "tcp" }],
+    environment = [for k, v in merge(local.common_env, {
+      PORT = "8080", DATABASE_URL = local.database_url, SQS_QUEUE_URL = aws_sqs_queue.main.url,
+      PROJECTION_TABLE = aws_dynamodb_table.projection.name, VALKEY_URL = local.valkey_url, CACHE_TTL_SECONDS = "90",
+      AUTH_ISSUER = local.issuer, AUTH_JWKS_URL = "${local.issuer}/.well-known/jwks.json",
+      AUTH_AUDIENCES = join(",", [for k in ["read", "write", "admin"] : aws_cognito_user_pool_client.clients[k].id]),
+      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.logs["api"].name
+    }) : { name = k, value = v }],
+    logConfiguration = { logDriver = "awslogs", options = { awslogs-group = aws_cloudwatch_log_group.logs["api"].name, awslogs-region = var.config.region, awslogs-stream-prefix = "api" } }
+  }])
+}
+resource "aws_ecs_service" "api" {
+  name = "${local.p}-api"
+  cluster = aws_ecs_cluster.api.id
+  task_definition = aws_ecs_task_definition.api.arn
+  launch_type = "FARGATE"
+  desired_count = 2
+  network_configuration { subnets = aws_subnet.private[*].id, security_groups = [aws_security_group.ecs.id], assign_public_ip = false }
+  load_balancer { target_group_arn = aws_lb_target_group.api.arn, container_name = "api", container_port = 8080 }
+  depends_on = [aws_lb_listener.api, aws_iam_role_policy.canonical]
+}
*** End Patch

*** Begin Patch
*** Add File: /workspace/submission/infra/iam.tf
+locals {
+  queue_arns = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn]
+  table_arns = [aws_dynamodb_table.projection.arn, "${aws_dynamodb_table.projection.arn}/index/AccountIndex"]
+  bucket_arns = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
+  key_arns = [for k in aws_kms_key.keys : k.arn]
+  log_arns = { for k, g in aws_cloudwatch_log_group.logs : k => "${g.arn}:*" }
+  workload_log = { ecs_execution = "api", ecs_task = "api", projector = "projector", relay = "relay", archiver = "archiver" }
+  crypto_keys = { ecs_task = ["messaging", "projection"], projector = ["messaging", "projection"], relay = ["messaging", "database"], archiver = ["audit", "database"] }
+  sqs_actions = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
+  ddb_actions = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
+  s3_actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
+  allows = {
+    ecs_execution = []
+    ecs_task = [
+      { Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"], Resource = local.table_arns }
+    ]
+    projector = [
+      { Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Allow", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"], Resource = local.table_arns }
+    ]
+    relay = [{ Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [aws_sqs_queue.main.arn] }]
+    archiver = [
+      { Effect = "Allow", Action = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"], Resource = ["${aws_s3_bucket.audit.arn}/ledger-audit/*"] },
+      { Effect = "Allow", Action = ["s3:ListBucket", "s3:GetBucketLocation"], Resource = [aws_s3_bucket.audit.arn] }
+    ]
+    scheduler = [{ Effect = "Allow", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.workers["relay"].arn, aws_lambda_function.workers["archiver"].arn] }]
+  }
+  denies = {
+    ecs_execution = [
+      { Effect = "Deny", Action = local.sqs_actions, Resource = local.queue_arns },
+      { Effect = "Deny", Action = local.ddb_actions, Resource = local.table_arns },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_arns }
+    ]
+    ecs_task = [
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_arns },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_arns }
+    ]
+    projector = [
+      { Effect = "Deny", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_arns },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_arns }
+    ]
+    relay = [
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = local.ddb_actions, Resource = local.table_arns },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_arns }
+    ]
+    archiver = [
+      { Effect = "Deny", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.bucket_arns },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = local.queue_arns },
+      { Effect = "Deny", Action = local.ddb_actions, Resource = local.table_arns }
+    ]
+    scheduler = [
+      { Effect = "Deny", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.workers["projector"].arn] },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = local.queue_arns },
+      { Effect = "Deny", Action = local.ddb_actions, Resource = local.table_arns },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_arns }
+    ]
+  }
+}
+resource "aws_iam_role_policy" "canonical" {
+  for_each = local.roles
+  name = "${local.p}-${each.key}-canonical"
+  role = aws_iam_role.roles[each.key].id
+  policy = jsonencode({ Version = "2012-10-17", Statement = concat(
+    local.allows[each.key], local.denies[each.key],
+    [{ Effect = "Deny", Action = ["kms:DisableKey", "kms:ScheduleKeyDeletion"], Resource = local.key_arns }],
+    [{ Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = [for k, v in aws_kms_key.keys : v.arn if !contains(lookup(local.crypto_keys, each.key, []), k)] }],
