        requireCustomerManaged(key, "kms:CancelKeyDeletion");
        if (lacksImportedKeyMaterial(key)) {
            key.setKeyState(PENDING_IMPORT);
            key.setEnabled(false);
        } else {
            key.setKeyState("Enabled");
        }
        key.setDeletionDate(0);
